def _make_wide_ternary_shift_binop(width: int, op: str, shift: int, dst_width: int | None = None) -> Module:
    """assign y = (sel ? a : b) << N / >> N; wide mux-shift regression."""
    if dst_width is None:
        dst_width = width
    op_tag = {"<<": "shl", ">>": "shr"}[op]
    module_name = f"wide_b_mux_{op_tag}_{width}_{shift}"
    if dst_width != width:
        module_name = f"{module_name}_{dst_width}"
    return Module(
        module_name,
        ports=[
            Port("sel", PortDirection.INPUT),
            Port("a", PortDirection.INPUT, width=_w(width)),
            Port("b", PortDirection.INPUT, width=_w(width)),
            Port("y", PortDirection.OUTPUT, width=_w(dst_width)),
        ],
        nets=[
            Net("sel", NetKind.WIRE),
            Net("a", NetKind.WIRE, width=_w(width)),
            Net("b", NetKind.WIRE, width=_w(width)),
            Net("y", NetKind.WIRE, width=_w(dst_width)),
        ],
        continuous_assigns=[
            ContinuousAssign(
                Identifier("y"),
                BinaryOp(op, TernaryOp(Identifier("sel"), Identifier("a"), Identifier("b")), Literal(shift, width=32)),
            ),
        ],
    )


