    op_tag = {"<<": "shl", ">>": "shr"}[op]
    return Module(
        f"wide_b_subs_{op_tag}_{src_width}_{dst_width}_{shift}",
        ports=[
            Port("a", PortDirection.INPUT, width=_w(src_width)),
            Port("b", PortDirection.INPUT, width=_w(src_width)),
            Port("y", PortDirection.OUTPUT, width=_w(dst_width)),
        ],
        nets=[
            Net("a", NetKind.WIRE, width=_w(src_width)),
            Net("b", NetKind.WIRE, width=_w(src_width)),
            Net("y", NetKind.WIRE, width=_w(dst_width)),
        ],
        continuous_assigns=[
            ContinuousAssign(
                Identifier("y"),
                BinaryOp(op, BinaryOp("-", Identifier("a"), Identifier("b")), Literal(shift, width=32)),
            ),
        ],
    )


