def _make_wide_seq_generic_concat_or_signal_tree(
    hi_width: int,
    lo_width: int,
    dst_width: int | None = None,
    *,
    tree_on_left: bool = True,
) -> Module:
    """always @(posedge clk) q <= {hi, lo} | c; wide generic concat NBA regression."""
    total_width = hi_width + lo_width
