def _make_wide_generic_concat_signal_tree_multi_by_mode(
    hi_width: int,
    lo_width: int,
    mode_tag: str,
    dst_width: int | None = None,
    *,
    tree_on_left: bool = True,
) -> Module:
    total_width = hi_width + lo_width
    if dst_width is None:
        dst_width = total_width
    out_and = "q_and" if mode_tag == "s" else "y_and"
    out_add = "q_add" if mode_tag == "s" else "y_add"
    concat_expr = Concatenation([Identifier("hi"), Identifier("lo")])
    expr_and = (
        BinaryOp("&", concat_expr, Identifier("c")) if tree_on_left else BinaryOp("&", Identifier("c"), concat_expr)
    )
    expr_add = (
        BinaryOp("+", concat_expr, Identifier("c")) if tree_on_left else BinaryOp("+", Identifier("c"), concat_expr)
    )
    side_tag = "lhs" if tree_on_left else "rhs"
    mod = Module(
        f"wide_{mode_tag}_sig_concat_multi_{side_tag}_{hi_width}_{lo_width}_{dst_width}",
        ports=[
            *([Port("clk", PortDirection.INPUT)] if mode_tag == "s" else []),
            Port("hi", PortDirection.INPUT, width=_w(hi_width)),
            Port("lo", PortDirection.INPUT, width=_w(lo_width)),
            Port("c", PortDirection.INPUT, width=_w(total_width)),
            Port(out_and, PortDirection.OUTPUT, width=_w(dst_width)),
            Port(out_add, PortDirection.OUTPUT, width=_w(dst_width)),
        ],
        nets=[
            *([Net("clk", NetKind.WIRE)] if mode_tag == "s" else []),
            Net("hi", NetKind.WIRE, width=_w(hi_width)),
            Net("lo", NetKind.WIRE, width=_w(lo_width)),
            Net("c", NetKind.WIRE, width=_w(total_width)),
            *(
                [Net(out_and, NetKind.WIRE, width=_w(dst_width)), Net(out_add, NetKind.WIRE, width=_w(dst_width))]
                if mode_tag == "b"
                else []
            ),
        ],
        variables=(
            [
                Variable(out_and, VariableKind.REG, width=_w(dst_width)),
                Variable(out_add, VariableKind.REG, width=_w(dst_width)),
            ]
            if mode_tag != "b"
            else []
        ),
        continuous_assigns=(
            [ContinuousAssign(Identifier(out_and), expr_and), ContinuousAssign(Identifier(out_add), expr_add)]
            if mode_tag == "b"
            else []
        ),
    )
    if mode_tag != "b":
        assign_and: BlockingAssign | NonblockingAssign
        assign_add: BlockingAssign | NonblockingAssign
        if mode_tag == "s":
            assign_and = NonblockingAssign(Identifier(out_and), expr_and)
            assign_add = NonblockingAssign(Identifier(out_add), expr_add)
        else:
            assign_and = BlockingAssign(Identifier(out_and), expr_and)
            assign_add = BlockingAssign(Identifier(out_add), expr_add)
        always_kwargs = {
            "sensitivity_type": SensitivityType.SEQUENTIAL if mode_tag == "s" else SensitivityType.COMBINATIONAL
        }
        if mode_tag == "s":
            always_kwargs["sensitivity_list"] = [SensitivityEdge("posedge", Identifier("clk"))]
        mod.always_blocks = [AlwaysBlock(SeqBlock([assign_and, assign_add]), **always_kwargs)]
    return mod


def _make_wide_generic_replication_signal_tree_multi_by_mode(
    src_width: int,
    count: int,
    mode_tag: str,
    dst_width: int | None = None,
    *,
    tree_on_left: bool = True,
) -> Module:
    total_width = src_width * count
    if dst_width is None:
        dst_width = total_width
    out_and = "q_and" if mode_tag == "s" else "y_and"
    out_add = "q_add" if mode_tag == "s" else "y_add"
    repl_expr = Replication(Literal(count, width=32), Identifier("a"))
    expr_and = BinaryOp("&", repl_expr, Identifier("b")) if tree_on_left else BinaryOp("&", Identifier("b"), repl_expr)
    expr_add = BinaryOp("+", repl_expr, Identifier("b")) if tree_on_left else BinaryOp("+", Identifier("b"), repl_expr)
    side_tag = "lhs" if tree_on_left else "rhs"
    mod = Module(
        f"wide_{mode_tag}_sig_repl_multi_{side_tag}_{src_width}_{count}_{dst_width}",
        ports=[
            *([Port("clk", PortDirection.INPUT)] if mode_tag == "s" else []),
            Port("a", PortDirection.INPUT, width=_w(src_width)),
            Port("b", PortDirection.INPUT, width=_w(total_width)),
            Port(out_and, PortDirection.OUTPUT, width=_w(dst_width)),
            Port(out_add, PortDirection.OUTPUT, width=_w(dst_width)),
        ],
        nets=[
            *([Net("clk", NetKind.WIRE)] if mode_tag == "s" else []),
            Net("a", NetKind.WIRE, width=_w(src_width)),
            Net("b", NetKind.WIRE, width=_w(total_width)),
            *(
                [Net(out_and, NetKind.WIRE, width=_w(dst_width)), Net(out_add, NetKind.WIRE, width=_w(dst_width))]
                if mode_tag == "b"
                else []
            ),
        ],
        variables=(
            [
                Variable(out_and, VariableKind.REG, width=_w(dst_width)),
                Variable(out_add, VariableKind.REG, width=_w(dst_width)),
            ]
            if mode_tag != "b"
            else []
        ),
        continuous_assigns=(
            [ContinuousAssign(Identifier(out_and), expr_and), ContinuousAssign(Identifier(out_add), expr_add)]
            if mode_tag == "b"
            else []
        ),
    )
    if mode_tag != "b":
        assign_and: BlockingAssign | NonblockingAssign
        assign_add: BlockingAssign | NonblockingAssign
        if mode_tag == "s":
            assign_and = NonblockingAssign(Identifier(out_and), expr_and)
            assign_add = NonblockingAssign(Identifier(out_add), expr_add)
        else:
            assign_and = BlockingAssign(Identifier(out_and), expr_and)
            assign_add = BlockingAssign(Identifier(out_add), expr_add)
        always_kwargs = {
            "sensitivity_type": SensitivityType.SEQUENTIAL if mode_tag == "s" else SensitivityType.COMBINATIONAL
        }
        if mode_tag == "s":
            always_kwargs["sensitivity_list"] = [SensitivityEdge("posedge", Identifier("clk"))]
        mod.always_blocks = [AlwaysBlock(SeqBlock([assign_and, assign_add]), **always_kwargs)]
    return mod


