def _make_wide_seq_generic_signed_ternary_shift_tree(
    width: int,
    shift: int,
    dst_width: int | None = None,
) -> Module:
    """always @(posedge clk) q <= $signed(sel ? a : b) >>> N; wide generic signed NBA regression."""
    if dst_width is None:
        dst_width = width
    mod = Module(
        f"wide_s_generic_signed_ternary_shift_{width}_{shift}_{dst_width}",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("sel", PortDirection.INPUT),
            Port("a", PortDirection.INPUT, width=_w(width)),
            Port("b", PortDirection.INPUT, width=_w(width)),
            Port("q", PortDirection.OUTPUT, width=_w(dst_width)),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("sel", NetKind.WIRE),
            Net("a", NetKind.WIRE, width=_w(width)),
            Net("b", NetKind.WIRE, width=_w(width)),
        ],
        variables=[Variable("q", VariableKind.REG, width=_w(dst_width))],
    )
    mod.always_blocks = [
        AlwaysBlock(
            NonblockingAssign(
                Identifier("q"),
                BinaryOp(
                    ">>>",
                    FunctionCall(
                        "$signed",
                        [TernaryOp(Identifier("sel"), Identifier("a"), Identifier("b"))],
                        is_system=True,
                    ),
                    Literal(shift, width=32),
                ),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


