def _make_wide_seq_generic_signed_add_const_xor_shift_var_tree(
    width: int,
    shift_width: int = 8,
    dst_width: int | None = None,
    literal_value: int = 0x1F0F0F0F,
    literal_width: int = 32,
) -> Module:
    """always @(posedge clk) q <= $signed((a + CONST) ^ b) >>> sh; wide generic signed variable-shift NBA regression."""
    if dst_width is None:
        dst_width = width
    mod = Module(
        f"wide_s_gen_sacxv_{width}_{shift_width}_{dst_width}",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("a", PortDirection.INPUT, width=_w(width)),
            Port("b", PortDirection.INPUT, width=_w(width)),
            Port("sh", PortDirection.INPUT, width=Range(Literal(shift_width - 1, width=32), Literal(0, width=32))),
            Port("q", PortDirection.OUTPUT, width=_w(dst_width)),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("a", NetKind.WIRE, width=_w(width)),
            Net("b", NetKind.WIRE, width=_w(width)),
            Net("sh", NetKind.WIRE, width=Range(Literal(shift_width - 1, width=32), Literal(0, width=32))),
        ],
        variables=[Variable("q", VariableKind.REG, width=_w(dst_width))],
    )
    mod.always_blocks = [
        AlwaysBlock(
            NonblockingAssign(
                Identifier("q"),
                BinaryOp(
                    ">>>",
                    FunctionCall(
                        "$signed",
                        [
                            BinaryOp(
                                "^",
                                BinaryOp("+", Identifier("a"), Literal(literal_value, width=literal_width)),
                                Identifier("b"),
                            )
                        ],
                        is_system=True,
                    ),
                    Identifier("sh"),
                ),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


