def _make_wide_signed_signal_xor_shift_module(
    name_tag: str,
    inner_op: str,
    width: int,
    *,
    mode: str,
    shift: int | None = None,
    shift_width: int = 8,
    dst_width: int | None = None,
) -> Module:
    if dst_width is None:
        dst_width = width

    mode_tag = {"continuous": "b", "combo": "c", "seq": "s"}[mode]
    is_var_shift = shift is None
    shift_tag = shift_width if is_var_shift else shift
    output_name = "q" if mode == "seq" else "y"
    output_port = Port(output_name, PortDirection.OUTPUT, width=_w(dst_width))

    ports = []
    nets = []
    if mode == "seq":
        ports.append(Port("clk", PortDirection.INPUT))
        nets.append(Net("clk", NetKind.WIRE))

    ports.extend(
        [
            Port("a", PortDirection.INPUT, width=_w(width)),
            Port("b", PortDirection.INPUT, width=_w(width)),
            Port("c", PortDirection.INPUT, width=_w(width)),
        ]
    )
    nets.extend(
        [
            Net("a", NetKind.WIRE, width=_w(width)),
            Net("b", NetKind.WIRE, width=_w(width)),
            Net("c", NetKind.WIRE, width=_w(width)),
        ]
    )
    if is_var_shift:
        shift_range = Range(Literal(shift_width - 1, width=32), Literal(0, width=32))
        ports.append(Port("sh", PortDirection.INPUT, width=shift_range))
        nets.append(Net("sh", NetKind.WIRE, width=shift_range))

    ports.append(output_port)
    if mode == "continuous":
        nets.append(Net(output_name, NetKind.WIRE, width=_w(dst_width)))

    shift_expr = Identifier("sh") if is_var_shift else Literal(shift, width=32)
    signed_expr = BinaryOp("^", BinaryOp(inner_op, Identifier("a"), Identifier("b")), Identifier("c"))
    full_expr = BinaryOp(">>>", FunctionCall("$signed", [signed_expr], is_system=True), shift_expr)

    if mode == "continuous":
        return Module(
            f"wide_{mode_tag}_gen_{name_tag}_{width}_{shift_tag}_{dst_width}",
            ports=ports,
            nets=nets,
            continuous_assigns=[ContinuousAssign(Identifier(output_name), full_expr)],
        )

    assign = BlockingAssign(Identifier(output_name), full_expr)
    sensitivity_type = SensitivityType.COMBINATIONAL
    if mode == "seq":
        assign = NonblockingAssign(Identifier(output_name), full_expr)
        sensitivity_type = SensitivityType.SEQUENTIAL

    mod = Module(
        f"wide_{mode_tag}_gen_{name_tag}_{width}_{shift_tag}_{dst_width}",
        ports=ports,
        nets=nets,
        variables=[Variable(output_name, VariableKind.REG, width=_w(dst_width))],
    )
    always_kwargs = {"sensitivity_type": sensitivity_type}
    if mode == "seq":
        always_kwargs["sensitivity_list"] = [SensitivityEdge("posedge", Identifier("clk"))]
    mod.always_blocks = [AlwaysBlock(assign, **always_kwargs)]
    return mod


def _make_wide_generic_signed_sub_xor_shift_var_tree(
    width: int,
    shift_width: int = 8,
    dst_width: int | None = None,
) -> Module:
    """assign y = $signed((a - b) ^ c) >>> sh; wide generic signed variable-shift regression."""
    return _make_wide_signed_signal_xor_shift_module(
        "ssxv",
        "-",
        width,
        mode="continuous",
        shift_width=shift_width,
        dst_width=dst_width,
    )


