def _make_counter() -> Module:
    """8-bit counter with synchronous reset.

    always @(posedge clk)
        if (rst) count <= 0;
        else count <= count + 1;
    """
    mod = Module(
        "counter",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("rst", PortDirection.INPUT),
            Port("count", PortDirection.OUTPUT, width=_w8()),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("rst", NetKind.WIRE),
        ],
        variables=[
            Variable("count", VariableKind.REG, width=_w8()),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            IfStatement(
                Identifier("rst"),
                NonblockingAssign(Identifier("count"), Literal(0, width=8)),
                NonblockingAssign(
                    Identifier("count"),
                    BinaryOp("+", Identifier("count"), Literal(1, width=8)),
                ),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


def _make_counter_with_enable() -> Module:
    """8-bit counter with enable and synchronous reset.

    always @(posedge clk)
        if (rst) count <= 0;
        else if (en) count <= count + 1;
    """
    mod = Module(
        "counter_en",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("rst", PortDirection.INPUT),
            Port("en", PortDirection.INPUT),
            Port("count", PortDirection.OUTPUT, width=_w8()),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("rst", NetKind.WIRE),
            Net("en", NetKind.WIRE),
        ],
        variables=[
            Variable("count", VariableKind.REG, width=_w8()),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            IfStatement(
                Identifier("rst"),
                NonblockingAssign(Identifier("count"), Literal(0, width=8)),
                IfStatement(
                    Identifier("en"),
                    NonblockingAssign(
                        Identifier("count"),
                        BinaryOp("+", Identifier("count"), Literal(1, width=8)),
                    ),
                ),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


def _make_shift_register() -> Module:
    """4-bit shift register with serial input.

    always @(posedge clk)
        sr <= {sr[2:0], din};
    """
    from veriforge.model.expressions import RangeSelect  # noqa: PLC0415

    w4 = Range(Literal(3, width=32), Literal(0, width=32))
    mod = Module(
        "shift_reg",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("din", PortDirection.INPUT),
            Port("sr", PortDirection.OUTPUT, width=w4),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("din", NetKind.WIRE),
        ],
        variables=[
            Variable("sr", VariableKind.REG, width=w4),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            NonblockingAssign(
                Identifier("sr"),
                Concatenation(
                    [
                        RangeSelect(Identifier("sr"), Literal(2, width=32), Literal(0, width=32)),
                        Identifier("din"),
                    ]
                ),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


def _make_fsm() -> Module:
    """3-state FSM: IDLE→RUN→DONE→IDLE.

    always @(posedge clk)
        if (rst) state <= 0;
        else case (state)
            0: if (go) state <= 1;
            1: state <= 2;
            2: state <= 0;
        endcase
    """
    w2 = Range(Literal(1, width=32), Literal(0, width=32))
    mod = Module(
        "fsm",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("rst", PortDirection.INPUT),
            Port("go", PortDirection.INPUT),
            Port("state", PortDirection.OUTPUT, width=w2),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("rst", NetKind.WIRE),
            Net("go", NetKind.WIRE),
        ],
        variables=[
            Variable("state", VariableKind.REG, width=w2),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            IfStatement(
                Identifier("rst"),
                NonblockingAssign(Identifier("state"), Literal(0, width=2)),
                CaseStatement(
                    "case",
                    Identifier("state"),
                    [
                        CaseItem(
                            [Literal(0, width=2)],
                            IfStatement(
                                Identifier("go"),
                                NonblockingAssign(Identifier("state"), Literal(1, width=2)),
                            ),
                        ),
                        CaseItem(
                            [Literal(1, width=2)],
                            NonblockingAssign(Identifier("state"), Literal(2, width=2)),
                        ),
                        CaseItem(
                            [Literal(2, width=2)],
                            NonblockingAssign(Identifier("state"), Literal(0, width=2)),
                        ),
                    ],
                ),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


def _make_combo_always_mux() -> Module:
    """Combinational always block mux.

    always @(*)
        if (sel) y = a;
        else y = b;
    """
    mod = Module(
        "combo_mux",
        ports=[
            Port("sel", PortDirection.INPUT),
            Port("a", PortDirection.INPUT, width=_w8()),
            Port("b", PortDirection.INPUT, width=_w8()),
            Port("y", PortDirection.OUTPUT, width=_w8()),
        ],
        nets=[
            Net("sel", NetKind.WIRE),
            Net("a", NetKind.WIRE, width=_w8()),
            Net("b", NetKind.WIRE, width=_w8()),
        ],
        variables=[
            Variable("y", VariableKind.REG, width=_w8()),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            IfStatement(
                Identifier("sel"),
                BlockingAssign(Identifier("y"), Identifier("a")),
                BlockingAssign(Identifier("y"), Identifier("b")),
            ),
            sensitivity_type=SensitivityType.COMBINATIONAL,
        ),
    ]
    return mod


def _make_mixed_cont_seq() -> Module:
    """Mixed continuous assign + sequential always.

    assign doubled = count << 1;
    always @(posedge clk)
        if (rst) count <= 0;
        else count <= count + 1;
    """
    mod = Module(
        "mixed",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("rst", PortDirection.INPUT),
            Port("count", PortDirection.OUTPUT, width=_w8()),
            Port("doubled", PortDirection.OUTPUT, width=_w8()),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("rst", NetKind.WIRE),
            Net("doubled", NetKind.WIRE, width=_w8()),
        ],
        variables=[
            Variable("count", VariableKind.REG, width=_w8()),
        ],
        continuous_assigns=[
            ContinuousAssign(
                Identifier("doubled"),
                BinaryOp("<<", Identifier("count"), Literal(1, width=8)),
            ),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            IfStatement(
                Identifier("rst"),
                NonblockingAssign(Identifier("count"), Literal(0, width=8)),
                NonblockingAssign(
                    Identifier("count"),
                    BinaryOp("+", Identifier("count"), Literal(1, width=8)),
                ),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


def _make_bit_select_lhs() -> Module:
    """always @(posedge clk) x[3] <= 1'b1;

    Start x=0, after one posedge x should be 8 (bit 3 set).
    """
    mod = Module(
        "bit_sel_lhs",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("x", PortDirection.OUTPUT, width=_w8()),
        ],
        nets=[Net("clk", NetKind.WIRE)],
        variables=[Variable("x", VariableKind.REG, width=_w8())],
    )
    mod.always_blocks = [
        AlwaysBlock(
            NonblockingAssign(
                BitSelect(Identifier("x"), Literal(3, width=32)),
                Literal(1, width=1),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


def _make_range_select_lhs() -> Module:
    """always @(posedge clk) x[5:2] <= 4'hA;

    Start x=0, after posedge x[5:2]=0xA → x = 0b00_1010_00 = 0x28.
    """
    mod = Module(
        "range_sel_lhs",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("x", PortDirection.OUTPUT, width=_w8()),
        ],
        nets=[Net("clk", NetKind.WIRE)],
        variables=[Variable("x", VariableKind.REG, width=_w8())],
    )
    mod.always_blocks = [
        AlwaysBlock(
            NonblockingAssign(
                RangeSelect(Identifier("x"), Literal(5, width=32), Literal(2, width=32)),
                Literal(0xA, width=4),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


def _make_part_select_lhs() -> Module:
    """always @(posedge clk) x[2 +: 4] <= 4'hA;

    Same result as range_select: x[5:2] = 0xA → x = 0x28.
    """
    mod = Module(
        "part_sel_lhs",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("x", PortDirection.OUTPUT, width=_w8()),
        ],
        nets=[Net("clk", NetKind.WIRE)],
        variables=[Variable("x", VariableKind.REG, width=_w8())],
    )
    mod.always_blocks = [
        AlwaysBlock(
            NonblockingAssign(
                PartSelect(Identifier("x"), Literal(2, width=32), Literal(4, width=32), "+:"),
                Literal(0xA, width=4),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
    ]
    return mod


