def _make_concat_dyn_range_lhs(mode: str) -> Module:
    """Write a concat containing a plain packed-signal dynamic range-select."""
    x_port = Port("x", PortDirection.INPUT, width=_w(4))
    msb_port = Port("msb", PortDirection.INPUT, width=_w(3))
    lsb_port = Port("lsb", PortDirection.INPUT, width=_w(3))
    data_port = Port("data", PortDirection.OUTPUT, width=_w(5))
    valid_port = Port("valid", PortDirection.OUTPUT)
    concat_lhs = Concatenation(
        [RangeSelect(Identifier("data"), Identifier("msb"), Identifier("lsb")), Identifier("valid")]
    )
    if mode == "cont":
        return Module(
            "concat_dyn_range_lhs_cont",
            ports=[x_port, msb_port, lsb_port, data_port, valid_port],
            nets=[
                Net("x", NetKind.WIRE, width=_w(4)),
                Net("msb", NetKind.WIRE, width=_w(3)),
                Net("lsb", NetKind.WIRE, width=_w(3)),
                Net("data", NetKind.WIRE, width=_w(5)),
                Net("valid", NetKind.WIRE),
            ],
            continuous_assigns=[ContinuousAssign(concat_lhs, Identifier("x"))],
        )

    mod = Module(
        f"concat_dyn_range_lhs_{mode}",
        ports=[Port("clk", PortDirection.INPUT), x_port, msb_port, lsb_port, data_port, valid_port]
        if mode == "seq"
        else [x_port, msb_port, lsb_port, data_port, valid_port],
        nets=[Net("clk", NetKind.WIRE)]
        + [
            Net("x", NetKind.WIRE, width=_w(4)),
            Net("msb", NetKind.WIRE, width=_w(3)),
            Net("lsb", NetKind.WIRE, width=_w(3)),
        ]
        if mode == "seq"
        else [
            Net("x", NetKind.WIRE, width=_w(4)),
            Net("msb", NetKind.WIRE, width=_w(3)),
            Net("lsb", NetKind.WIRE, width=_w(3)),
        ],
        variables=[Variable("data", VariableKind.REG, width=_w(5)), Variable("valid", VariableKind.REG)],
    )
    assign_stmt: Statement
    if mode == "combo":
        assign_stmt = BlockingAssign(concat_lhs, Identifier("x"))
        mod.always_blocks = [AlwaysBlock(SeqBlock([assign_stmt]), sensitivity_type=SensitivityType.COMBINATIONAL)]
    else:
        assign_stmt = NonblockingAssign(concat_lhs, Identifier("x"))
        mod.always_blocks = [
            AlwaysBlock(
                SeqBlock([assign_stmt]),
                sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
                sensitivity_type=SensitivityType.SEQUENTIAL,
            )
        ]
    return mod


def _make_concat_dyn_range_lhs_cont() -> Module:
    return _make_concat_dyn_range_lhs("cont")


