_WIDE_CONCAT_LHS_PARTS = [
    ("a", 2),
    ("b", 32),
    ("c", 3),
    ("d", 8),
    ("e", 1),
    ("f", 32),
    ("g", 4),
    ("h", 16),
    ("i", 32),
    ("j", 2),
]


def _pack_concat_parts(parts: list[tuple[str, Value]]) -> Value:
    width = sum(part.width for _, part in parts)
    val = 0
    mask = 0
    for _, part in parts:
        val = (val << part.width) | part.val
        mask = (mask << part.width) | part.mask
    return Value(val, width=width, mask=mask)


def _make_wide_concat_lhs_cont() -> Module:
    """assign {a..j} = x; with x wide enough to force wide-signal slicing."""
    ports = [Port("x", PortDirection.INPUT, width=_w(sum(width for _, width in _WIDE_CONCAT_LHS_PARTS)))]
    nets = [Net("x", NetKind.WIRE, width=_w(sum(width for _, width in _WIDE_CONCAT_LHS_PARTS)))]
    for name, width in _WIDE_CONCAT_LHS_PARTS:
        part_width = _w(width) if width > 1 else None
        ports.append(Port(name, PortDirection.OUTPUT, width=part_width))
        nets.append(Net(name, NetKind.WIRE, width=part_width))
    return Module(
        "wide_concat_lhs_cont",
        ports=ports,
        nets=nets,
        continuous_assigns=[
            ContinuousAssign(
                Concatenation([Identifier(name) for name, _ in _WIDE_CONCAT_LHS_PARTS]),
                Identifier("x"),
            ),
        ],
    )


def _make_mem_read_write() -> Module:
    """reg [7:0] mem [0:3]; combo read mem[addr] with external write.

    No initial block (compiled engine doesn't support them yet).
    Uses mem_write() API + combo read for testing.
    """
    mod = Module(
        "mem_rw",
        ports=[
            Port("addr", PortDirection.INPUT, width=Range(Literal(1, width=32), Literal(0, width=32))),
            Port("out", PortDirection.OUTPUT, width=_w8()),
        ],
        nets=[
            Net("addr", NetKind.WIRE, width=Range(Literal(1, width=32), Literal(0, width=32))),
        ],
        variables=[
            Variable("out", VariableKind.REG, width=_w8()),
            Variable(
                "mem",
                VariableKind.REG,
                width=_w8(),
                dimensions=[Range(Literal(0, width=32), Literal(3, width=32))],
            ),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            body=BlockingAssign(
                Identifier("out"),
                BitSelect(Identifier("mem"), Identifier("addr")),
            ),
            sensitivity_type=SensitivityType.COMBINATIONAL,
        ),
    ]
    return mod


