def _make_struct_mem_field_concat(mode: str) -> Module:
    """Write a concat of struct-backed memory fields in the requested assignment mode."""
    st = StructType(
        [
            StructField("data", "logic", width=_w8()),
            StructField("valid", "logic"),
        ],
        packed=True,
    )
    td = TypedefDecl("bus_t", struct_type=st)
    ports = [
        Port("addr", PortDirection.INPUT, width=_w(1)),
        Port("in_bus", PortDirection.INPUT, width=_w(9)),
    ]
    nets = [
        Net("addr", NetKind.WIRE, width=_w(1)),
        Net("in_bus", NetKind.WIRE, width=_w(9)),
    ]
