def _make_wide_struct_mem_element_read(mode: str) -> Module:
    """Write a wide packed-struct memory element from a bus, then read back the whole element."""
    data_width = 65
    total_width = data_width + 1
    st = StructType(
        [
            StructField("data", "logic", width=_w(data_width)),
            StructField("valid", "logic"),
        ],
        packed=True,
    )
    td = TypedefDecl("wide_bus_t", struct_type=st)
    ports = [
        Port("addr", PortDirection.INPUT, width=_w(1)),
        Port("in_bus", PortDirection.INPUT, width=_w(total_width)),
        Port("out_bus", PortDirection.OUTPUT, width=_w(total_width)),
    ]
    nets = [
        Net("addr", NetKind.WIRE, width=_w(1)),
        Net("in_bus", NetKind.WIRE, width=_w(total_width)),
        Net("out_bus", NetKind.WIRE, width=_w(total_width)),
    ]
    if mode == "seq":
        ports.insert(0, Port("clk", PortDirection.INPUT))
        nets.insert(0, Net("clk", NetKind.WIRE))
    mod = Module(
        f"wide_struct_mem_element_read_{mode}",
        ports=ports,
        nets=nets,
        variables=[
            Variable(
                "mem",
                VariableKind.REG,
                width=_w(total_width),
                type_name="wide_bus_t",
                dimensions=[Range(Literal(0, width=32), Literal(1, width=32))],
            ),
        ],
    )
    mem_elem = BitSelect(Identifier("mem"), Identifier("addr"))
    mod.continuous_assigns = [ContinuousAssign(Identifier("out_bus"), mem_elem)]
    if mode == "cont":
        mod.continuous_assigns = [
            ContinuousAssign(mem_elem, Identifier("in_bus")),
            *mod.continuous_assigns,
        ]
    else:
        assign = (
            NonblockingAssign(mem_elem, Identifier("in_bus"))
            if mode == "seq"
            else BlockingAssign(mem_elem, Identifier("in_bus"))
        )
        sensitivity_list = [SensitivityEdge("posedge", Identifier("clk"))] if mode == "seq" else None
        sensitivity_type = SensitivityType.SEQUENTIAL if mode == "seq" else SensitivityType.COMBINATIONAL
        mod.always_blocks = [
            AlwaysBlock(
                SeqBlock([assign]),
                sensitivity_list=sensitivity_list,
                sensitivity_type=sensitivity_type,
            )
        ]
    mod.typedefs = [td]
    return mod


