def _make_wide_struct_whole_mem_copy(mode: str) -> Module:
    """Copy a wide packed-struct memory array to another memory array."""
    data_width = 65
    total_width = data_width + 1
    st = StructType(
        [
            StructField("data", "logic", width=_w(data_width)),
            StructField("valid", "logic"),
        ],
        packed=True,
    )
    td = TypedefDecl("wide_bus_t", struct_type=st)
    ports = [
        Port("out0", PortDirection.OUTPUT, width=_w(total_width)),
        Port("out1", PortDirection.OUTPUT, width=_w(total_width)),
    ]
    nets = [
        Net("out0", NetKind.WIRE, width=_w(total_width)),
        Net("out1", NetKind.WIRE, width=_w(total_width)),
    ]
    if mode == "seq":
        ports.insert(0, Port("clk", PortDirection.INPUT))
        nets.insert(0, Net("clk", NetKind.WIRE))
    mod = Module(
        f"wide_struct_whole_mem_copy_{mode}",
        ports=ports,
        nets=nets,
        variables=[
            Variable(
                "src",
                VariableKind.REG,
                width=_w(total_width),
                type_name="wide_bus_t",
                dimensions=[Range(Literal(0, width=32), Literal(1, width=32))],
            ),
            Variable(
                "dst",
                VariableKind.REG,
                width=_w(total_width),
                type_name="wide_bus_t",
                dimensions=[Range(Literal(0, width=32), Literal(1, width=32))],
            ),
        ],
    )
    if mode == "combo":
        mod.always_blocks = [
            AlwaysBlock(
                SeqBlock([BlockingAssign(Identifier("dst"), Identifier("src"))]),
                sensitivity_type=SensitivityType.COMBINATIONAL,
            )
        ]
    else:
        mod.always_blocks = [
            AlwaysBlock(
                SeqBlock([NonblockingAssign(Identifier("dst"), Identifier("src"))]),
                sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
                sensitivity_type=SensitivityType.SEQUENTIAL,
            )
        ]
    mod.continuous_assigns = [
        ContinuousAssign(Identifier("out0"), BitSelect(Identifier("dst"), Literal(0, width=32))),
        ContinuousAssign(Identifier("out1"), BitSelect(Identifier("dst"), Literal(1, width=32))),
    ]
    mod.typedefs = [td]
    return mod


