def _make_module_with_stmt(stmt) -> Module:
    """Helper: minimal module whose always_comb body is a single statement."""
    from veriforge.model.behavioral import SensitivityType

    mod = Module(
        "fail_fast_test",
        ports=[Port("y", PortDirection.OUTPUT, width=_w8())],
        nets=[],
        variables=[Variable("y", VariableKind.REG, width=_w8())],
    )
    mod.always_blocks = [AlwaysBlock(SeqBlock([stmt]), sensitivity_type=SensitivityType.COMBINATIONAL)]
    return mod


def _make_always_clk_gen() -> Module:
    """always #5 clk = ~clk; — canonical slow clock-generator pattern."""
    mod = Module(
        "clk_gen",
        ports=[Port("clk", PortDirection.OUTPUT)],
        nets=[Net("clk", NetKind.WIRE)],
    )
    mod.always_blocks = [
        AlwaysBlock(
            ForeverLoop(
                SeqBlock(
                    [
                        DelayControl(Literal(5, width=32)),
                        BlockingAssign(Identifier("clk"), UnaryOp("~", Identifier("clk"))),
                    ]
                )
            ),
            sensitivity_list=[],
        )
    ]
    return mod


def _make_always_event_control() -> Module:
    """always @(posedge trigger) y = ~y; — always block with event control."""
    from veriforge.model.statements import EventControl

    mod = Module(
        "event_ctrl",
        ports=[
            Port("trigger", PortDirection.INPUT),
            Port("y", PortDirection.OUTPUT),
        ],
        nets=[Net("trigger", NetKind.WIRE)],
        variables=[Variable("y", VariableKind.REG)],
    )
    mod.always_blocks = [
        AlwaysBlock(
            SeqBlock(
                [
                    EventControl(
                        events=[SensitivityEdge("posedge", Identifier("trigger"))],
                        body=BlockingAssign(Identifier("y"), UnaryOp("~", Identifier("y"))),
                    ),
                ]
            ),
            sensitivity_list=[],
        )
    ]
    return mod


def _make_initial_timing_single_delay() -> Module:
    """initial #10 y = 1; — initial block with a single delay."""
    mod = Module(
        "init_timing_delay",
        ports=[Port("y", PortDirection.OUTPUT)],
        variables=[Variable("y", VariableKind.REG)],
    )
    mod.initial_blocks = [
        InitialBlock(
            SeqBlock(
                [
                    DelayControl(Literal(10, width=32)),
                    BlockingAssign(Identifier("y"), Literal(1, width=1)),
                ]
            )
        )
    ]
    return mod


def _make_initial_timing_delay_loop() -> Module:
    """initial while(1) begin #10 clk = ~clk; end — slow timing loop."""
    mod = Module(
        "init_timing_delay_loop",
        ports=[Port("clk", PortDirection.OUTPUT)],
        variables=[Variable("clk", VariableKind.REG)],
    )
    mod.initial_blocks = [
        InitialBlock(
            WhileLoop(
                Literal(1, width=1),
                SeqBlock(
                    [
                        DelayControl(Literal(10, width=32)),
                        BlockingAssign(Identifier("clk"), UnaryOp("~", Identifier("clk"))),
                    ]
                ),
            )
        )
    ]
    return mod


def _wide_mem_addr_range() -> Range:
    """2-bit address range for depth-4 memories."""
    return Range(Literal(1, width=32), Literal(0, width=32))


def _make_wide_mem_nba_write_combo_read(elem_width: int) -> Module:
    """always @(posedge clk) mem[wr_addr] <= data_in;  always @(*) data_out = mem[rd_addr];"""
    mod = Module(
        f"wide_mem_nba_rw_{elem_width}",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("data_in", PortDirection.INPUT, width=_w(elem_width)),
            Port("wr_addr", PortDirection.INPUT, width=_wide_mem_addr_range()),
            Port("rd_addr", PortDirection.INPUT, width=_wide_mem_addr_range()),
            Port("data_out", PortDirection.OUTPUT, width=_w(elem_width)),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("data_in", NetKind.WIRE, width=_w(elem_width)),
            Net("wr_addr", NetKind.WIRE, width=_wide_mem_addr_range()),
            Net("rd_addr", NetKind.WIRE, width=_wide_mem_addr_range()),
        ],
        variables=[
            Variable("data_out", VariableKind.REG, width=_w(elem_width)),
            Variable(
                "mem",
                VariableKind.REG,
                width=_w(elem_width),
                dimensions=[Range(Literal(0, width=32), Literal(3, width=32))],
            ),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            body=NonblockingAssign(
                BitSelect(Identifier("mem"), Identifier("wr_addr")),
                Identifier("data_in"),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
        AlwaysBlock(
            body=BlockingAssign(
                Identifier("data_out"),
                BitSelect(Identifier("mem"), Identifier("rd_addr")),
            ),
            sensitivity_type=SensitivityType.COMBINATIONAL,
        ),
    ]
    return mod


def _make_wide_mem_blocking_seq_write_combo_read(elem_width: int) -> Module:
    """always @(posedge clk) mem[wr_addr] = data_in;  always @(*) data_out = mem[rd_addr];"""
    mod = Module(
        f"wide_mem_blk_rw_{elem_width}",
        ports=[
            Port("clk", PortDirection.INPUT),
            Port("data_in", PortDirection.INPUT, width=_w(elem_width)),
            Port("wr_addr", PortDirection.INPUT, width=_wide_mem_addr_range()),
            Port("rd_addr", PortDirection.INPUT, width=_wide_mem_addr_range()),
            Port("data_out", PortDirection.OUTPUT, width=_w(elem_width)),
        ],
        nets=[
            Net("clk", NetKind.WIRE),
            Net("data_in", NetKind.WIRE, width=_w(elem_width)),
            Net("wr_addr", NetKind.WIRE, width=_wide_mem_addr_range()),
            Net("rd_addr", NetKind.WIRE, width=_wide_mem_addr_range()),
        ],
        variables=[
            Variable("data_out", VariableKind.REG, width=_w(elem_width)),
            Variable(
                "mem",
                VariableKind.REG,
                width=_w(elem_width),
                dimensions=[Range(Literal(0, width=32), Literal(3, width=32))],
            ),
        ],
    )
    mod.always_blocks = [
        AlwaysBlock(
            body=BlockingAssign(
                BitSelect(Identifier("mem"), Identifier("wr_addr")),
                Identifier("data_in"),
            ),
            sensitivity_list=[SensitivityEdge("posedge", Identifier("clk"))],
            sensitivity_type=SensitivityType.SEQUENTIAL,
        ),
        AlwaysBlock(
            body=BlockingAssign(
                Identifier("data_out"),
                BitSelect(Identifier("mem"), Identifier("rd_addr")),
            ),
            sensitivity_type=SensitivityType.COMBINATIONAL,
        ),
    ]
    return mod


def _w8s() -> Range:
    """8-bit range [7:0]."""
    return Range(Literal(7, width=32), Literal(0, width=32))


def _w16() -> Range:
    """16-bit range [15:0]."""
    return Range(Literal(15, width=32), Literal(0, width=32))


def _w1() -> Range:
    """1-bit range [0:0]."""
    return Range(Literal(0, width=32), Literal(0, width=32))


def _make_signed_cmp_module() -> Module:
    """assign lt = a < b;  assign gt = a > b;  with signed a, b."""
    return Module(
        "signed_cmp",
        nets=[
            Net("a", NetKind.WIRE, width=_w8s(), signed=True),
            Net("b", NetKind.WIRE, width=_w8s(), signed=True),
            Net("lt", NetKind.WIRE, width=_w1()),
            Net("gt", NetKind.WIRE, width=_w1()),
        ],
        continuous_assigns=[
            ContinuousAssign(Identifier("lt"), BinaryOp("<", Identifier("a"), Identifier("b"))),
            ContinuousAssign(Identifier("gt"), BinaryOp(">", Identifier("a"), Identifier("b"))),
        ],
    )


def _make_unsigned_cmp_module() -> Module:
    """assign lt = a < b;  assign gt = a > b;  with UNSIGNED a, b (signed=False)."""
    return Module(
        "unsigned_cmp",
        nets=[
            Net("a", NetKind.WIRE, width=_w8s(), signed=False),
            Net("b", NetKind.WIRE, width=_w8s(), signed=False),
            Net("lt", NetKind.WIRE, width=_w1()),
            Net("gt", NetKind.WIRE, width=_w1()),
        ],
        continuous_assigns=[
            ContinuousAssign(Identifier("lt"), BinaryOp("<", Identifier("a"), Identifier("b"))),
            ContinuousAssign(Identifier("gt"), BinaryOp(">", Identifier("a"), Identifier("b"))),
        ],
    )


def _make_mixed_signed_unsigned_cmp_module() -> Module:
    """assign lt = a < b;  a signed, b unsigned."""
    return Module(
        "mixed_cmp",
        nets=[
            Net("a", NetKind.WIRE, width=_w8s(), signed=True),
            Net("b", NetKind.WIRE, width=_w8s(), signed=False),
            Net("lt", NetKind.WIRE, width=_w1()),
        ],
        continuous_assigns=[
            ContinuousAssign(Identifier("lt"), BinaryOp("<", Identifier("a"), Identifier("b"))),
        ],
    )


def _make_signed_widen_module() -> Module:
    """assign w = a;  a is signed 8-bit, w is 16-bit output."""
    return Module(
        "signed_widen",
        nets=[
            Net("a", NetKind.WIRE, width=_w8s(), signed=True),
            Net("w", NetKind.WIRE, width=_w16()),
        ],
        continuous_assigns=[
            ContinuousAssign(Identifier("w"), Identifier("a")),
        ],
    )


def _make_signed_arith_widen_module() -> Module:
    """assign sum = a + b;  a,b signed 8-bit, sum 16-bit."""
    return Module(
        "signed_arith",
        nets=[
            Net("a", NetKind.WIRE, width=_w8s(), signed=True),
            Net("b", NetKind.WIRE, width=_w8s(), signed=True),
            Net("sum", NetKind.WIRE, width=_w16()),
        ],
        continuous_assigns=[
            ContinuousAssign(Identifier("sum"), BinaryOp("+", Identifier("a"), Identifier("b"))),
        ],
    )


def _make_signed_ashr_module() -> Module:
    """assign y = a >>> 2;  a signed 8-bit, y 8-bit."""
    return Module(
        "signed_ashr",
        nets=[
            Net("a", NetKind.WIRE, width=_w8s(), signed=True),
            Net("y", NetKind.WIRE, width=_w8s()),
        ],
        continuous_assigns=[
            ContinuousAssign(Identifier("y"), BinaryOp(">>>", Identifier("a"), Literal(2, width=8))),
        ],
    )


