def _make_add_chain_module(k: int):
    """k inputs a0..a(k-1), one reg result = a0 + a1 + ... + a(k-1)."""
    from veriforge.dsl import Module, posedge

    m = Module(f"add_chain_{k}")
    clk = m.input("clk")
    rst = m.input("rst")
    operands = [m.input(f"a{i}", width=16) for i in range(k)]
    result = m.reg("result", width=16)
    with m.always(posedge(clk)):
        with m.if_(rst):
            result <<= 0
        with m.else_():
            s = operands[0]
            for i in range(1, k):
                s = s + operands[i]
            result <<= s
    return m.build()


def _make_or_chain_module(k: int):
    """k inputs a0..a(k-1), one output wire result = a0 | a1 | ... | a(k-1)."""
    from veriforge.dsl import Module

    m = Module(f"or_chain_{k}")
    operands = [m.input(f"a{i}", width=8) for i in range(k)]
    result = m.output("result", width=8)
    s = operands[0]
    for i in range(1, k):
        s = s | operands[i]
    m.assign(result, s)
    return m.build()


def _make_ternary_chain_module(k: int):
    """Right-recursive k-deep ternary mux via continuous assign.

    result = a0 ? d0 : (a1 ? d1 : (a2 ? d2 : ... : dk))
    A right-recursive chain of k ternaries exercises _emit_ternary_value_mask_exprs
    which without caching recurses 2^k times.
    """
    from veriforge.dsl import Module, mux

    m = Module(f"ternary_chain_{k}")
    sels = [m.input(f"a{i}") for i in range(k)]
    datas = [m.input(f"d{i}", width=8) for i in range(k + 1)]
    result = m.output("result", width=8)
    # Build right-recursive: start from the innermost (default) and work outward
    expr = datas[k]
    for i in range(k - 1, -1, -1):
        expr = mux(sels[i], datas[i], expr)
    m.assign(result, expr)
    return m.build()


def _make_ternary_chain_32bit_module(k: int, name: str | None = None):
    """Right-recursive k-deep ternary mux with 32-bit data signals.

    Matches the gfwx-fpga norm_sum pattern: 24-deep chain, 32-bit outputs.
    """
    from veriforge.dsl import Module, mux

    m = Module(name or f"ternary_chain_32b_{k}")
    sels = [m.input(f"sel{i}") for i in range(k)]
    datas = [m.input(f"d{i}", width=32) for i in range(k + 1)]
    result = m.output("result", width=32)
    expr = datas[k]
    for i in range(k - 1, -1, -1):
        expr = mux(sels[i], datas[i], expr)
    m.assign(result, expr)
    return m.build()


def _make_ternary_chain_wide_branch_module(k: int):
    """k-deep ternary chain where the innermost branch is a wide-signal range-select.

    The last fallthrough data is w[31:0] where w is 128-bit — exercises the B1
    fix path (narrow LHS, wide RHS signal accessed via range-select).
    """
    from veriforge.dsl import Module
    from veriforge.model.expressions import RangeSelect, Identifier, Literal, TernaryOp
    from veriforge.model.assignments import ContinuousAssign

    m = Module(f"ternary_chain_wide_{k}")
    for i in range(k):
        m.input(f"sel{i}")
    for i in range(k):
        m.input(f"d{i}", width=32)
    m.input("w", width=128)
    m.output("result", width=32)

    mod = m.build()
    # Build chain: innermost = w[31:0]
    wide_slice = RangeSelect(target=Identifier("w"), msb=Literal(31), lsb=Literal(0))
    expr = wide_slice
    for i in range(k - 1, -1, -1):
        expr = TernaryOp(
            condition=Identifier(f"sel{i}"),
            true_expr=Identifier(f"d{i}"),
            false_expr=expr,
        )
    mod.continuous_assigns.append(ContinuousAssign(lhs=Identifier("result"), rhs=expr))
    return mod


def _make_or_of_ternaries_module(k: int):
    """CCA: result = (sel0 ? a0 : b0) | (sel1 ? a1 : b1) | ... | (sel_{k-1} ? a_{k-1} : b_{k-1}).

    This exercises Task 6's mask hoisting for |/& chains containing TernaryOp branches.
    """
    from veriforge.dsl import Module, mux

    m = Module(f"or_of_ternaries_{k}")
    sels = [m.input(f"sel{i}") for i in range(k)]
    a_sigs = [m.input(f"a{i}", width=32) for i in range(k)]
    b_sigs = [m.input(f"b{i}", width=32) for i in range(k)]
    result = m.output("result", width=32)

    # Left-associative: ((sel0?a0:b0) | (sel1?a1:b1)) | ...
    expr = mux(sels[0], a_sigs[0], b_sigs[0])
    for i in range(1, k):
        expr = expr | mux(sels[i], a_sigs[i], b_sigs[i])
    m.assign(result, expr)
    return m.build()


def _make_or_chain_of_sels_module():
    """CCA: a multi-level |/& tree followed by comparison to test cross-hoisting.

    result = ((a | b | c | d) == 0) ? 0 : 1  — exercises chain + comparison.
    """
    from veriforge.dsl import Module

    m = Module("or_chain_sel")
    a = m.input("a", width=32)
    b = m.input("b", width=32)
    c = m.input("c", width=32)
    d = m.input("d", width=32)
    result = m.output("result", width=32)
    # Build OR-reduction then use as selector
    or_chain = ((a | b) | c) | d
    m.assign(result, or_chain)
    return m.build()


def _make_signed_wide_shift_module(shift_amt: int, *, name: str | None = None):
    """CCA: assign result[31:0] = $signed(w) >>> shift_amt (w is 128 bits)."""
    from veriforge.dsl import Module

    mod_name = name or f"signed_wide_shift_{shift_amt}"
    m = Module(mod_name)
    m.input("w", width=128)
    m.output("result", width=32)
    mod = m.build()
    mod.continuous_assigns.append(
        ContinuousAssign(
            lhs=Identifier("result"),
            rhs=BinaryOp(
                ">>>",
                FunctionCall("$signed", [Identifier("w")], is_system=True),
                Literal(str(shift_amt)),
            ),
        )
    )
    return mod


def _make_narrow64_binop_module(op: str, *, lhs_width: int = 64, a_width: int = 64, b_width: int = 64, name: str):
    """CCA: assign result = a <op> b with given port widths."""
    from veriforge.dsl import Module

    m = Module(name)
    m.input("a", width=a_width)
    m.input("b", width=b_width)
    m.output("result", width=lhs_width)
    mod = m.build()
    mod.continuous_assigns.append(
        ContinuousAssign(
            lhs=Identifier("result"),
            rhs=BinaryOp(op, Identifier("a"), Identifier("b")),
        )
    )
    return mod


def _make_bitwise_cond_seq_module(op: str, name: str):
    """Sequential module: if ((a + b) <op> b) result <= 1 else result <= 0.

    a and b are 3-bit regs so that (a+b) can have bit1 set while the LSB is 0,
    exposing truncation to 1 bit.
    """
    from veriforge.dsl import Module, posedge

    m = Module(name)
    clk = m.input("clk")
    a = m.reg("a", width=3)
    b = m.reg("b", width=3)
    result = m.reg("result", width=1)

    compound = a + b
    if op == "&":
        cond = compound & b
    elif op == "|":
        cond = compound | b
    elif op == "^":
        cond = compound ^ b
    else:
        raise ValueError(op)

    with m.always(posedge(clk)):
        with m.if_(cond):
            result <<= 1
        with m.else_():
            result <<= 0

    return m.build()


def _make_bitwise_cond_ca_module(op: str, name: str):
    """Combinational module: assign result = ((a + b) <op> b) ? 1 : 0."""
    from veriforge.dsl import Module, mux

    m = Module(name)
    a = m.input("a", width=3)
    b = m.input("b", width=3)
    result = m.output("result", width=1)

    compound = a + b
    if op == "&":
        cond = compound & b
    elif op == "|":
        cond = compound | b
    elif op == "^":
        cond = compound ^ b
    else:
        raise ValueError(op)

    m.assign(result, mux(cond, 1, 0))
    return m.build()
